import 'package:flutter/material.dart';import '../models/models.dart';import '../services/data_service.dart';import '../services/pdf_service.dart';
class OrdersScreen extends StatelessWidget{final AppUser user;OrdersScreen({super.key,required this.user});final ds=DataService();final pdf=PdfService();@override Widget build(BuildContext c)=>StreamBuilder<List<OrderModel>>(stream:ds.orders(repId:user.role==UserRole.admin?null:user.id),builder:(c,s){final os=s.data??[];if(os.isEmpty)return const Center(child:Text('لا توجد طلبات بعد'));return ListView.builder(padding:const EdgeInsets.all(10),itemCount:os.length,itemBuilder:(c,i){final o=os[i];return Card(child:ExpansionTile(title:Text('طلب ${o.id.substring(0,8)}'),subtitle:Text('${o.salesRepName} • ${statusLabel(o.status)} • ${o.lines.length} أصناف'),children:[Padding(padding:const EdgeInsets.symmetric(horizontal:16),child:Column(children:[...o.lines.map((x)=>ListTile(dense:true,title:Text(x.productName),subtitle:Text('${x.code} • ${x.note}'),trailing:Text('${x.quantity} ${x.unit}'))),Row(mainAxisAlignment:MainAxisAlignment.end,children:[IconButton(tooltip:'PDF',onPressed:()=>pdf.printOrder(o),icon:const Icon(Icons.picture_as_pdf)),if(user.role==UserRole.admin)PopupMenuButton<OrderStatus>(onSelected:(v)=>ds.updateStatus(o.id,v),itemBuilder:(_)=>OrderStatus.values.map((v)=>PopupMenuItem(value:v,child:Text(statusLabel(v)))).toList(),child:const Icon(Icons.change_circle))])]))]));});}
}
